Q: Managing production .env with cd pipeline A: <pre><code># ==========================================================
# 1. Get projects
# 2. Get groups
# 3. Get users
# 4. Filter projects/groups/users created after Oct 2025
# 5. Get group members
# 6. Get project members
# 7. Build final user filter
# 8. Get MRs, branches, commits only for filtered projects/users
# 9. Generate counts
# 10. Export CSV reports

# CONFIGURATION


$GitLabURL = &quot;https://gitlab.yourcompany.com&quot;
$token     = &quot;YOUR_TOKEN&quot;

$headers = @{
    &quot;PRIVATE-TOKEN&quot; = $token
}

$cutOffDate = [datetime]&quot;2025-10-01&quot;

$outputFolder = &quot;\AUDIT_GITLAB_PSSCRIPT&quot;

if (!(Test-Path $outputFolder)) {
    New-Item -ItemType Directory -Path $outputFolder | Out-Null
}

# 0 means fetch all commit pages per branch.
# If repositories are huge, set this as 1, 2, 5 etc.
$MaxCommitPagesPerBranch = 0

# True means activity reports include only activity matching final filtered users.
# False means include all MR/branch/commit activity from filtered projects.
$ApplyUserFilterToActivity = $true

# ==========================================================
# OUTPUT FILES

$projectsFile                = Join-Path $outputFolder &quot;projects.csv&quot;
$groupsFile                  = Join-Path $outputFolder &quot;groups.csv&quot;
$usersFile                   = Join-Path $outputFolder &quot;users.csv&quot;

$groupMembersFile            = Join-Path $outputFolder &quot;group_members.csv&quot;
$projectMembersFile          = Join-Path $outputFolder &quot;project_members.csv&quot;
$finalFilteredUsersFile      = Join-Path $outputFolder &quot;final_filtered_users.csv&quot;

$projectActivitySummaryFile  = Join-Path $outputFolder &quot;project_activity_summary.csv&quot;

$mrDetailsFile               = Join-Path $outputFolder &quot;merge_requests_details.csv&quot;
$mrCreatedCountFile          = Join-Path $outputFolder &quot;merge_requests_count_by_creator.csv&quot;
$mrMergedCountFile           = Join-Path $outputFolder &quot;merge_requests_count_by_mergedby.csv&quot;

$branchDetailsFile           = Join-Path $outputFolder &quot;branches_details.csv&quot;
$branchCreatorCountFile      = Join-Path $outputFolder &quot;branches_count_by_creator_approx.csv&quot;

$commitDetailsFile           = Join-Path $outputFolder &quot;commits_details.csv&quot;
$commitAuthorCountFile       = Join-Path $outputFolder &quot;commits_count_by_author.csv&quot;
$committerCountFile          = Join-Path $outputFolder &quot;commits_count_by_committer.csv&quot;
$uniqueCommitAuthorCountFile = Join-Path $outputFolder &quot;unique_commits_count_by_author.csv&quot;

# ==========================================================
# FUNCTION: GET GITLAB DATA WITH PAGINATION
# Modified from your yesterday script.
# Supports endpoints with or without existing query string.


function Get-GitLabData {

    param(
        [string]$Endpoint,
        [int]$MaxPages = 0
    )

    $page = 1
    $perPage = 100
    $allData = @()

    do {

        if ($Endpoint -match &quot;\?&quot;) {
            $url = &quot;$GitLabURL/api/v4/$Endpoint&amp;per_page=$perPage&amp;page=$page&quot;
        }
        else {
            $url = &quot;$GitLabURL/api/v4/$Endpoint?per_page=$perPage&amp;page=$page&quot;
        }

        Write-Host &quot;Fetching $Endpoint - page $page&quot;

        try {
            $result = Invoke-RestMethod `
                -Uri $url `
                -Method Get `
                -Headers $headers

            if ($null -eq $result) {
                $resultArray = @()
            }
            else {
                $resultArray = @($result)
            }

            if ($resultArray.Count -gt 0) {
                $allData += $resultArray
            }

            if ($MaxPages -gt 0 -and $page -ge $MaxPages) {
                break
            }

            $page++
        }
        catch {
            Write-Warning &quot;API call failed:&quot;
            Write-Warning $url
            Write-Warning $_.Exception.Message
            break
        }

    } while ($resultArray.Count -eq $perPage)

    return $allData
}

# ==========================================================
# FUNCTION: ENCODE VALUE FOR URL
# Used for branch names with slash or special characters.


function Encode-GitLabValue {

    param(
        [string]$Value
    )

    return [System.Uri]::EscapeDataString($Value)
}

# ==========================================================
# TEST TOKEN


Write-Host &quot;Testing GitLab token...&quot;

try {
    $currentUser = Invoke-RestMethod `
        -Uri &quot;$GitLabURL/api/v4/user&quot; `
        -Method Get `
        -Headers $headers

    Write-Host &quot;Token valid. Logged in as: $($currentUser.name) / $($currentUser.username)&quot;
}
catch {
    Write-Error &quot;Token validation failed. Please check GitLab URL, token, and permissions.&quot;
    return
}

# ==========================================================
# YESTERDAY SCRIPT PART
# Get projects, groups, users


Write-Host &quot;&quot;
Write-Host &quot;Getting all projects...&quot;
$projects = Get-GitLabData &quot;projects&quot;

Write-Host &quot;&quot;
Write-Host &quot;Getting all groups...&quot;
$groups = Get-GitLabData &quot;groups&quot;

Write-Host &quot;&quot;
Write-Host &quot;Getting all users...&quot;
$users = Get-GitLabData &quot;users&quot;

# ==========================================================
# FILTER PROJECTS, GROUPS, USERS AFTER 2025-10-01
# Important change: id is added in filteredprojects


$filteredprojects = $projects | Where-Object {
    ([datetime]$_.created_at) -ge $cutOffDate
} | Select-Object `
    id,
    name,
    path_with_namespace,
    created_at,
    creator_id,
    web_url,
    default_branch,
    visibility,
    archived,
    last_activity_at

$filteredgroups = $groups | Where-Object {
    ([datetime]$_.created_at) -ge $cutOffDate
} | Select-Object `
    id,
    name,
    full_path,
    created_at,
    web_url

$filteredusers = $users | Where-Object {
    ([datetime]$_.created_at) -ge $cutOffDate
} | Select-Object `
    id,
    name,
    username,
    email,
    created_at,
    state,
    web_url

Write-Host &quot;&quot;
Write-Host &quot;Filtered projects count : $($filteredprojects.Count)&quot;
Write-Host &quot;Filtered groups count   : $($filteredgroups.Count)&quot;
Write-Host &quot;Filtered users count    : $($filteredusers.Count)&quot;

# ==========================================================
# EXPORT YESTERDAY OUTPUTS


$filteredprojects |
    Export-Csv $projectsFile -NoTypeInformation -Encoding UTF8

$filteredgroups |
    Export-Csv $groupsFile -NoTypeInformation -Encoding UTF8

$filteredusers |
    Export-Csv $usersFile -NoTypeInformation -Encoding UTF8

# ==========================================================
# BUILD USER LOOKUP FROM ALL USERS
# Used to get repo creator name from creator_id


$userLookupById = @{}

foreach ($user in $users) {
    if ($null -ne $user.id) {
        $userLookupById[[string]$user.id] = $user
    }
}

function Get-UserFromLookup {

    param(
        [string]$UserId
    )

    if (:IsNullOrWhiteSpace($UserId)) {
        return $null
    }

    if ($userLookupById.ContainsKey([string]$UserId)) {
        return $userLookupById[[string]$UserId]
    }

    return $null
}

# ==========================================================
# NEW REQUIREMENT PART
# STEP 4: GET GROUP MEMBERS FROM EXISTING FILTERED GROUPS


$groupMembersReport = @()
$projectMembersReport = @()
$FinalFilteredUsers = @()

foreach ($group in $filteredgroups) {

    Write-Host &quot;&quot;
    Write-Host &quot;Getting group members for: $($group.full_path)&quot;

    $groupMembers = Get-GitLabData &quot;groups/$($group.id)/members/all&quot;

    foreach ($member in $groupMembers) {

        $groupMembersReport += [PSCustomObject]@{
            GroupId             = $group.id
            GroupName           = $group.name
            GroupFullPath       = $group.full_path
            GroupCreatedAt      = $group.created_at

            UserId              = $member.id
            Name                = $member.name
            Username            = $member.username
            AccessLevel         = $member.access_level
            State               = $member.state
            MembershipCreatedAt = $member.created_at
            ExpiresAt           = $member.expires_at
            WebUrl              = $member.web_url
        }

        $FinalFilteredUsers += [PSCustomObject]@{
            UserId    = [string]$member.id
            Name      = $member.name
            Username  = $member.username
            Email     = &quot;&quot;
            Source    = &quot;GroupMember&quot;
            SourceRef = $group.full_path
        }
    }
}

# ==========================================================
# STEP 5: GET PROJECT MEMBERS FROM EXISTING FILTERED PROJECTS


foreach ($project in $filteredprojects) {

    Write-Host &quot;&quot;
    Write-Host &quot;Getting project members for: $($project.path_with_namespace)&quot;

    $projectMembers = Get-GitLabData &quot;projects/$($project.id)/members/all&quot;

    foreach ($member in $projectMembers) {

        $projectMembersReport += [PSCustomObject]@{
            ProjectId           = $project.id
            ProjectName         = $project.name
            ProjectPath         = $project.path_with_namespace
            ProjectCreatedAt    = $project.created_at

            UserId              = $member.id
            Name                = $member.name
            Username            = $member.username
            AccessLevel         = $member.access_level
            State               = $member.state
            MembershipCreatedAt = $member.created_at
            ExpiresAt           = $member.expires_at
            WebUrl              = $member.web_url
        }

        $FinalFilteredUsers += [PSCustomObject]@{
            UserId    = [string]$member.id
            Name      = $member.name
            Username  = $member.username
            Email     = &quot;&quot;
            Source    = &quot;ProjectMember&quot;
            SourceRef = $project.path_with_namespace
        }
    }
}

# ==========================================================
# STEP 6: BUILD USER FILTER
# Includes:
# 1. Users filtered from users API
# 2. Group members
# 3. Project members


foreach ($user in $filteredusers) {

    $FinalFilteredUsers += [PSCustomObject]@{
        UserId    = [string]$user.id
        Name      = $user.name
        Username  = $user.username
        Email     = $user.email
        Source    = &quot;FilteredUser&quot;
        SourceRef = &quot;users_created_after_2025_10_01&quot;
    }
}

$FinalFilteredUsers = $FinalFilteredUsers |
    Where-Object {
        -not :IsNullOrWhiteSpace($_.UserId) -or
        -not :IsNullOrWhiteSpace($_.Username) -or
        -not :IsNullOrWhiteSpace($_.Name) -or
        -not :IsNullOrWhiteSpace($_.Email)
    } |
    Sort-Object UserId, Username, Name -Unique

$FilteredUserIds = @(
    $FinalFilteredUsers |
    Where-Object { -not :IsNullOrWhiteSpace($_.UserId) } |
    ForEach-Object { [string]$_.UserId }
)

$FilteredUserNames = @(
    $FinalFilteredUsers |
    Where-Object { -not :IsNullOrWhiteSpace($_.Name) } |
    ForEach-Object { $_.Name.ToLower() }
)

$FilteredUserUsernames = @(
    $FinalFilteredUsers |
    Where-Object { -not :IsNullOrWhiteSpace($_.Username) } |
    ForEach-Object { $_.Username.ToLower() }
)

$FilteredUserEmails = @(
    $FinalFilteredUsers |
    Where-Object { -not :IsNullOrWhiteSpace($_.Email) } |
    ForEach-Object { $_.Email.ToLower() }
)

Write-Host &quot;&quot;
Write-Host &quot;Final filtered users count: $($FinalFilteredUsers.Count)&quot;

# ==========================================================
# FUNCTION: CHECK IF USER IS IN FILTERED USER LIST


function Test-FilteredUser {

    param(
        [string]$UserId,
        [string]$Name,
        [string]$Username,
        [string]$Email
    )

    if ($FinalFilteredUsers.Count -eq 0) {
        return $true
    }

    if (-not :IsNullOrWhiteSpace($UserId)) {
        if ($FilteredUserIds -contains [string]$UserId) {
            return $true
        }
    }

    if (-not :IsNullOrWhiteSpace($Name)) {
        if ($FilteredUserNames -contains $Name.ToLower()) {
            return $true
        }
    }

    if (-not :IsNullOrWhiteSpace($Username)) {
        if ($FilteredUserUsernames -contains $Username.ToLower()) {
            return $true
        }
    }

    if (-not :IsNullOrWhiteSpace($Email)) {
        if ($FilteredUserEmails -contains $Email.ToLower()) {
            return $true
        }
    }

    return $false
}

# ==========================================================
# REPORT ARRAYS


$projectActivitySummary = @()
$mrDetailsReport = @()
$branchDetailsReport = @()
$commitDetailsReport = @()

# ==========================================================
# STEP 7: GET MRs, BRANCHES, COMMITS ONLY FOR FILTERED PROJECTS/USERS


foreach ($project in $filteredprojects) {

    $projectId   = $project.id
    $projectName = $project.name
    $projectPath = $project.path_with_namespace

    $repoCreatorName = &quot;&quot;
    $repoCreatorUsername = &quot;&quot;
    $repoCreatorEmail = &quot;&quot;

    $repoCreator = Get-UserFromLookup -UserId $project.creator_id

    if ($null -ne $repoCreator) {
        $repoCreatorName = $repoCreator.name
        $repoCreatorUsername = $repoCreator.username
        $repoCreatorEmail = $repoCreator.email
    }

    Write-Host &quot;&quot;
    Write-Host &quot;==================================================&quot;
    Write-Host &quot;Processing project activity: $projectPath&quot;
    Write-Host &quot;==================================================&quot;

    # ======================================================
    # MERGE REQUESTS


    Write-Host &quot;Getting merge requests...&quot;

    $mergeRequests = Get-GitLabData &quot;projects/$projectId/merge_requests?state=all&quot;

    foreach ($mr in $mergeRequests) {

        $mrCreatorId = &quot;&quot;
        $mrCreatorName = &quot;&quot;
        $mrCreatorUsername = &quot;&quot;

        if ($null -ne $mr.author) {
            $mrCreatorId = [string]$mr.author.id
            $mrCreatorName = $mr.author.name
            $mrCreatorUsername = $mr.author.username
        }

        $mergedById = &quot;&quot;
        $mergedByName = &quot;&quot;
        $mergedByUsername = &quot;&quot;

        if ($null -ne $mr.merged_by) {
            $mergedById = [string]$mr.merged_by.id
            $mergedByName = $mr.merged_by.name
            $mergedByUsername = $mr.merged_by.username
        }

        $isMrCreatorFiltered = Test-FilteredUser `
            -UserId $mrCreatorId `
            -Name $mrCreatorName `
            -Username $mrCreatorUsername `
            -Email &quot;&quot;

        $isMergedByFiltered = Test-FilteredUser `
            -UserId $mergedById `
            -Name $mergedByName `
            -Username $mergedByUsername `
            -Email &quot;&quot;

        if ($ApplyUserFilterToActivity -eq $false -or $isMrCreatorFiltered -or $isMergedByFiltered) {

            $mrDetailsReport += [PSCustomObject]@{
                ProjectId              = $projectId
                ProjectName            = $projectName
                ProjectPath            = $projectPath
                ProjectCreatedDate     = $project.created_at

                RepoCreatorId          = $project.creator_id
                RepoCreatorName        = $repoCreatorName
                RepoCreatorUsername    = $repoCreatorUsername
                RepoCreatorEmail       = $repoCreatorEmail

                MergeRequestId         = $mr.id
                MergeRequestIid        = $mr.iid
                MergeRequestTitle      = $mr.title
                MergeRequestState      = $mr.state

                SourceBranch           = $mr.source_branch
                TargetBranch           = $mr.target_branch

                MergeCreatedById       = $mrCreatorId
                MergeCreatedByName     = $mrCreatorName
                MergeCreatedByUsername = $mrCreatorUsername
                MergeCreatedDate       = $mr.created_at

                MergedById             = $mergedById
                MergedByName           = $mergedByName
                MergedByUsername       = $mergedByUsername
                MergedDate             = $mr.merged_at

                ClosedDate             = $mr.closed_at
                UpdatedDate            = $mr.updated_at
                WebUrl                 = $mr.web_url
            }
        }
    }

    # ======================================================
    # BRANCHES

    Write-Host &quot;Getting branches...&quot;

    $branches = Get-GitLabData &quot;projects/$projectId/repository/branches&quot;

    foreach ($branch in $branches) {

        $branchName = $branch.name
        $encodedBranchName = Encode-GitLabValue -Value $branchName

        Write-Host &quot;Processing branch: $branchName&quot;

        # Commits are needed for:
        # 1. Commit details
        # 2. Approx branch creator/date
        $branchCommits = Get-GitLabData `
            -Endpoint &quot;projects/$projectId/repository/commits?ref_name=$encodedBranchName&quot; `
            -MaxPages $MaxCommitPagesPerBranch

        # GitLab branch API does not give exact creator/date.
        # Oldest fetched commit is used as approximation.
        $branchCreatedByName = &quot;&quot;
        $branchCreatedByEmail = &quot;&quot;
        $branchCreatedDate = &quot;&quot;
        $branchCreatedCommitId = &quot;&quot;

        if ($branchCommits.Count -gt 0) {
            $firstCommit = $branchCommits[-1]

            $branchCreatedByName = $firstCommit.author_name
            $branchCreatedByEmail = $firstCommit.author_email
            $branchCreatedDate = $firstCommit.created_at
            $branchCreatedCommitId = $firstCommit.id
        }

        $isBranchCreatorFiltered = Test-FilteredUser `
            -UserId &quot;&quot; `
            -Name $branchCreatedByName `
            -Username &quot;&quot; `
            -Email $branchCreatedByEmail

        if ($ApplyUserFilterToActivity -eq $false -or $isBranchCreatorFiltered) {

            $branchDetailsReport += [PSCustomObject]@{
                ProjectId                    = $projectId
                ProjectName                  = $projectName
                ProjectPath                  = $projectPath
                ProjectCreatedDate           = $project.created_at

                RepoCreatorId                = $project.creator_id
                RepoCreatorName              = $repoCreatorName
                RepoCreatorUsername          = $repoCreatorUsername
                RepoCreatorEmail             = $repoCreatorEmail

                BranchName                   = $branchName
                DefaultBranch                = $project.default_branch
                ProtectedBranch              = $branch.protected
                DevelopersCanPush            = $branch.developers_can_push
                DevelopersCanMerge           = $branch.developers_can_merge
                CanPush                      = $branch.can_push

                BranchCreatedByNameApprox    = $branchCreatedByName
                BranchCreatedByEmailApprox   = $branchCreatedByEmail
                BranchCreatedDateApprox      = $branchCreatedDate
                BranchCreatedCommitIdApprox  = $branchCreatedCommitId

                LastCommitId                 = $branch.commit.id
                LastCommitShortId            = $branch.commit.short_id
                LastCommitTitle              = $branch.commit.title
                LastCommitAuthorName         = $branch.commit.author_name
                LastCommitAuthorEmail        = $branch.commit.author_email
                LastCommitDate               = $branch.commit.created_at

                TotalCommitsFetchedForBranch = $branchCommits.Count
            }
        }

        # ==================================================
        # COMMITS

        foreach ($commit in $branchCommits) {

            $isCommitAuthorFiltered = Test-FilteredUser `
                -UserId &quot;&quot; `
                -Name $commit.author_name `
                -Username &quot;&quot; `
                -Email $commit.author_email

            $isCommitterFiltered = Test-FilteredUser `
                -UserId &quot;&quot; `
                -Name $commit.committer_name `
                -Username &quot;&quot; `
                -Email $commit.committer_email

            if ($ApplyUserFilterToActivity -eq $false -or $isCommitAuthorFiltered -or $isCommitterFiltered) {

                $commitDetailsReport += [PSCustomObject]@{
                    ProjectId           = $projectId
                    ProjectName         = $projectName
                    ProjectPath         = $projectPath
                    ProjectCreatedDate  = $project.created_at

                    RepoCreatorId       = $project.creator_id
                    RepoCreatorName     = $repoCreatorName
                    RepoCreatorUsername = $repoCreatorUsername
                    RepoCreatorEmail    = $repoCreatorEmail

                    BranchName          = $branchName

                    CommitId            = $commit.id
                    ShortId             = $commit.short_id
                    CommitTitle         = $commit.title
                    CommitMessage       = $commit.message

                    CommitAuthorName    = $commit.author_name
                    CommitAuthorEmail   = $commit.author_email
                    CommitAuthoredDate  = $commit.authored_date

                    CommitterName       = $commit.committer_name
                    CommitterEmail      = $commit.committer_email
                    CommittedDate       = $commit.committed_date

                    CreatedAt           = $commit.created_at
                    WebUrl              = $commit.web_url
                }
            }
        }
    }

    # ======================================================
    # PROJECT ACTIVITY SUMMARY

    $projectMRs = @($mrDetailsReport | Where-Object { $_.ProjectId -eq $projectId })
    $projectBranches = @($branchDetailsReport | Where-Object { $_.ProjectId -eq $projectId })
    $projectCommits = @($commitDetailsReport | Where-Object { $_.ProjectId -eq $projectId })

    $projectActivitySummary += [PSCustomObject]@{
        ProjectId                  = $projectId
        ProjectName                = $projectName
        ProjectPath                = $projectPath
        ProjectCreatedDate         = $project.created_at

        RepoCreatorId              = $project.creator_id
        RepoCreatorName            = $repoCreatorName
        RepoCreatorUsername        = $repoCreatorUsername
        RepoCreatorEmail           = $repoCreatorEmail

        MergeRequestCount          = $projectMRs.Count
        BranchCount                = $projectBranches.Count
        CommitRowsFetched          = $projectCommits.Count
        UniqueCommitCount          = @($projectCommits | Select-Object CommitId -Unique).Count

        UniqueMergeCreators        = (($projectMRs | Where-Object { $_.MergeCreatedByName } | Select-Object -ExpandProperty MergeCreatedByName -Unique) -join &quot;; &quot;)
        UniqueMergedByUsers        = (($projectMRs | Where-Object { $_.MergedByName } | Select-Object -ExpandProperty MergedByName -Unique) -join &quot;; &quot;)
        UniqueBranchCreatorsApprox = (($projectBranches | Where-Object { $_.BranchCreatedByNameApprox } | Select-Object -ExpandProperty BranchCreatedByNameApprox -Unique) -join &quot;; &quot;)
        UniqueCommitAuthors        = (($projectCommits | Where-Object { $_.CommitAuthorName } | Select-Object -ExpandProperty CommitAuthorName -Unique) -join &quot;; &quot;)
        UniqueCommitters           = (($projectCommits | Where-Object { $_.CommitterName } | Select-Object -ExpandProperty CommitterName -Unique) -join &quot;; &quot;)
    }
}

# ==========================================================
# STEP 8: GENERATE COUNTS

$mrCreatedCountReport = $mrDetailsReport |
    Group-Object ProjectPath, MergeCreatedByName, MergeCreatedByUsername |
    ForEach-Object {
        $first = $_.Group[0]

        [PSCustomObject]@{
            ProjectPath               = $first.ProjectPath
            MergeCreatedByName        = $first.MergeCreatedByName
            MergeCreatedByUsername    = $first.MergeCreatedByUsername
            MergeRequestsCreatedCount = $_.Count
        }
    }

$mrMergedCountReport = $mrDetailsReport |
    Where-Object { -not :IsNullOrWhiteSpace($_.MergedByName) } |
    Group-Object ProjectPath, MergedByName, MergedByUsername |
    ForEach-Object {
        $first = $_.Group[0]

        [PSCustomObject]@{
            ProjectPath              = $first.ProjectPath
            MergedByName             = $first.MergedByName
            MergedByUsername         = $first.MergedByUsername
            MergeRequestsMergedCount = $_.Count
        }
    }

$branchCreatorCountReport = $branchDetailsReport |
    Group-Object ProjectPath, BranchCreatedByNameApprox, BranchCreatedByEmailApprox |
    ForEach-Object {
        $first = $_.Group[0]

        [PSCustomObject]@{
            ProjectPath                = $first.ProjectPath
            BranchCreatedByNameApprox  = $first.BranchCreatedByNameApprox
            BranchCreatedByEmailApprox = $first.BranchCreatedByEmailApprox
            BranchesCreatedCountApprox = $_.Count
        }
    }

$commitAuthorCountReport = $commitDetailsReport |
    Group-Object ProjectPath, CommitAuthorName, CommitAuthorEmail |
    ForEach-Object {
        $first = $_.Group[0]

        [PSCustomObject]@{
            ProjectPath          = $first.ProjectPath
            CommitAuthorName     = $first.CommitAuthorName
            CommitAuthorEmail    = $first.CommitAuthorEmail
            CommitsAuthoredCount = $_.Count
        }
    }

$committerCountReport = $commitDetailsReport |
    Group-Object ProjectPath, CommitterName, CommitterEmail |
    ForEach-Object {
        $first = $_.Group[0]

        [PSCustomObject]@{
            ProjectPath           = $first.ProjectPath
            CommitterName         = $first.CommitterName
            CommitterEmail        = $first.CommitterEmail
            CommitsCommittedCount = $_.Count
        }
    }

# This removes duplicate commits because same commit can appear in multiple branches.
$uniqueCommitAuthorCountReport = $commitDetailsReport |
    Sort-Object ProjectPath, CommitId -Unique |
    Group-Object ProjectPath, CommitAuthorName, CommitAuthorEmail |
    ForEach-Object {
        $first = $_.Group[0]

        [PSCustomObject]@{
            ProjectPath                = $first.ProjectPath
            CommitAuthorName           = $first.CommitAuthorName
            CommitAuthorEmail          = $first.CommitAuthorEmail
            UniqueCommitsAuthoredCount = $_.Count
        }
    }

# ==========================================================
# EXPORT NEW OUTPUTS

$groupMembersReport |
    Sort-Object GroupFullPath, Name |
    Export-Csv $groupMembersFile -NoTypeInformation -Encoding UTF8

$projectMembersReport |
    Sort-Object ProjectPath, Name |
    Export-Csv $projectMembersFile -NoTypeInformation -Encoding UTF8

$FinalFilteredUsers |
    Sort-Object Name, Username |
    Export-Csv $finalFilteredUsersFile -NoTypeInformation -Encoding UTF8

$projectActivitySummary |
    Sort-Object ProjectPath |
    Export-Csv $projectActivitySummaryFile -NoTypeInformation -Encoding UTF8

$mrDetailsReport |
    Sort-Object ProjectPath, MergeCreatedByName, MergeCreatedDate |
    Export-Csv $mrDetailsFile -NoTypeInformation -Encoding UTF8

$mrCreatedCountReport |
    Sort-Object ProjectPath, MergeCreatedByName |
    Export-Csv $mrCreatedCountFile -NoTypeInformation -Encoding UTF8

$mrMergedCountReport |
    Sort-Object ProjectPath, MergedByName |
    Export-Csv $mrMergedCountFile -NoTypeInformation -Encoding UTF8

$branchDetailsReport |
    Sort-Object ProjectPath, BranchName |
    Export-Csv $branchDetailsFile -NoTypeInformation -Encoding UTF8

